import { useId, useEffect, useRef, useLayoutEffect } from 'react';

export function Dialog({ open, onClose, title, children }) {
  const id = useId();
  const dialogRef = useRef(null);
  const initialFocusRef = useRef(null);
  const previousBodyOverflow = useRef('');

  useEffect(() => {
    if (open) {
      document.body.style.overflow = 'hidden';
      previousBodyOverflow.current = document.body.style.overflow;

      const focusableElements = dialogRef.current.querySelectorAll(
        'a[href], button, input:not([type="hidden"]), select, textarea, [tabindex]:not([tabindex="-1"])'
      );

      if (initialFocusRef.current) {
        initialFocusRef.current.focus();
      } else if (focusableElements.length > 0) {
        focusableElements[0].focus();
      } else {
        dialogRef.current.focus();
      }

      const handleKeyDown = (event) => {
        if (event.key === 'Escape') {
          onClose();
        }
      };

      const handleMouseDown = (event) => {
        if (event.target === dialogRef.current) {
          event.preventDefault();
        }
      };

      document.addEventListener('keydown', handleKeyDown);
      document.addEventListener('mousedown', handleMouseDown);

      return () => {
        document.body.style.overflow = previousBodyOverflow.current;
        document.removeEventListener('keydown', handleKeyDown);
        document.removeEventListener('mousedown', handleMouseDown);
      };
    }
  }, [open, onClose]);

  useLayoutEffect(() => {
    if (open) {
      const focusableElements = dialogRef.current.querySelectorAll(
        'a[href], button, input:not([type="hidden"]), select, textarea, [tabindex]:not([tabindex="-1"])'
      );

      const handleFocus = (event) => {
        if (event.target === dialogRef.current) {
          if (initialFocusRef.current) {
            initialFocusRef.current.focus();
          } else if (focusableElements.length > 0) {
            focusableElements[0].focus();
          } else {
            dialogRef.current.focus();
          }
        }
      };

      dialogRef.current.addEventListener('focusin', handleFocus);

      return () => {
        dialogRef.current.removeEventListener('focusin', handleFocus);
      };
    }
  }, [open]);

  useEffect(() => {
    if (open) {
      const handleBackdropClick = (event) => {
        if (event.target === dialogRef.current) {
          onClose();
        }
      };

      dialogRef.current.addEventListener('click', handleBackdropClick);

      return () => {
        dialogRef.current.removeEventListener('click', handleBackdropClick);
      };
    }
  }, [open, onClose]);

  useEffect(() => {
    if (!open) {
      const previouslyFocusedElement = document.activeElement;
      if (previouslyFocusedElement && document.body.contains(previouslyFocusedElement)) {
        previouslyFocusedElement.focus();
      }
    }
  }, [open]);

  if (!open) return null;

  return (
    <div data-testid="backdrop" onClick={onClose}>
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby={id}
        tabIndex={-1}
        ref={dialogRef}
      >
        <h2 id={id}>{title}</h2>
        {children}
      </div>
    </div>
  );
}
